import{_ as a,a as r,b as i,c as e}from"./chunks/presets-04.Dx-DqE4-.js";import{_ as o,o as n,c as s,a3 as l}from"./chunks/framework.D1iekJsc.js";const v=JSON.parse('{"title":"预设","description":"MiniTavern 提示词预设：基础提示词和可排序的提示词列表，切换角色扮演写法；采样参数仍在模型设置。","frontmatter":{"title":"预设","description":"MiniTavern 提示词预设：基础提示词和可排序的提示词列表，切换角色扮演写法；采样参数仍在模型设置。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"预设 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 提示词预设：基础提示词和可排序的提示词列表，切换角色扮演写法；采样参数仍在模型设置。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/presets"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/presets"}]]},"headers":[],"relativePath":"manual/presets.md","filePath":"manual/presets.md","lastUpdated":1791862671000}'),g={name:"manual/presets.md"};function p(c,t,h,d,u,m){return n(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="预设" tabindex="-1">预设 <a class="header-anchor" href="#预设" aria-label="Permalink to &quot;预设&quot;">​</a></h1><p>路径：底部 <strong>设置</strong> → <strong>预设</strong>。</p><p>预设是一整套提示词结构，用来改角色扮演的写法和约束。温度等采样不在这里，仍在 <strong>模型设置</strong>。</p><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="设置里的预设入口"><figcaption>1 · 设置 → 预设</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="预设列表"><figcaption>2 · 列表与新建</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="编辑预设"><figcaption>3 · 名字、基础提示词、提示词列表</figcaption></figure><figure class="shot-step"><img src="'+e+'" alt="新建提示词"><figcaption>4 · 新建提示词</figcaption></figure></div><h2 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h2><ol><li>右上角 <strong>新建</strong> 可以选择新建，或导入 SillyTavern Chat Completion 预设。导入时会忽略采样参数，并提示到模型设置里配置。</li><li>新安装时只有带 <strong>默认</strong> 标记的那一条。它不能编辑，也不能删除。</li><li>一行右侧的菜单可以置顶、设为默认、编辑、复制、导出、删除。</li><li>新建和复制都会先进入编辑页，点 <strong>保存</strong> 之后才出现在列表里。</li></ol><h2 id="编辑预设" tabindex="-1">编辑预设 <a class="header-anchor" href="#编辑预设" aria-label="Permalink to &quot;编辑预设&quot;">​</a></h2><ul><li><strong>名字</strong>必填。</li><li><strong>基础提示词</strong>里可以改人设、角色描述、性格、场景、示例对话开头、新对话开头、世界书。</li><li><strong>提示词</strong>列表可以搜索。长按拖动排序。开关打开的会参与普通发送；关掉的进未激活，不再注入。</li><li>点 <strong>添加</strong> 进入新建提示词。自定义条目可以编辑、复制、删除。内置条目只能改名字和内容。</li></ul><p>角色卡上的主提示词、历史后指令会盖过预设里对应的条目。场景正文的优先级是：聊天设置，然后角色卡，最后才是预设基础提示词里的纯文本。</p><p>继续、重新生成、智能回复不读这套预设。普通发送才会按列表顺序拼进去。</p><h2 id="新建提示词" tabindex="-1">新建提示词 <a class="header-anchor" href="#新建提示词" aria-label="Permalink to &quot;新建提示词&quot;">​</a></h2><ol><li><strong>名字</strong>必填。</li><li><strong>角色</strong>默认是 SYSTEM，也可以改成别的角色。</li><li><strong>注入位置</strong>选 <strong>相对</strong> 时，这条插在列表里的当前位置。选 <strong>对话中</strong> 时才会出现 <strong>注入深度</strong>，按深度插进历史。</li><li><strong>内容</strong>里可以写提示词，也能用宏。</li><li>点 <strong>保存</strong> 回到预设编辑页。</li></ol><h2 id="只改这一聊" tabindex="-1">只改这一聊 <a class="header-anchor" href="#只改这一聊" aria-label="Permalink to &quot;只改这一聊&quot;">​</a></h2><p>路径：对话页 → <strong>聊天设置</strong> → 模型 → <strong>预设</strong>。</p><p>默认是 <strong>跟随默认预设</strong>。关掉之后，可以为这一聊另选一条，不影响其它对话。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./model-link">模型连接</a>：采样仍在模型设置</li><li><a href="./persona">人设</a> · <a href="./lorebook">世界书</a>：基础提示词里会引用它们</li></ul>',18)])])}const T=o(g,[["render",p]]);export{v as __pageData,T as default};
